#[test]
fn test_resistor() {
    let r = Resistor::new("10k");
    assert_eq!(r.ref_prefix(), "R");
    assert_eq!(r.pin_ids(), strings(&["1", "2"]));
    assert_eq!(r.value(), "10k");
    assert!(r.internal_connections().is_empty());
    assert_eq!(
        r.kicad(),
        Some(KicadPartInfo {
            footprint: Some("test:R_0603".parse().unwrap()),
            pins: BTreeMap::from([
                ("1".into(), KicadPinInfo::new("1", None, PinType::Passive)),
                ("2".into(), KicadPinInfo::new("2", None, PinType::Passive)),
            ]),
            lib_source: Some(LibId::new("test", "R").unwrap()),
            fields: vec![],
            flags: PartFlags::default(),
            datasheet: None,
            description: Some("Resistor".into()),
        })
    );
    assert_eq!(
        r.spice(),
        Some(SpicePartInfo::element(SpiceElement::new(
            'R',
            ["1", "2"],
            "10k"
        )))
    );
}

#[test]
fn test_value_in_kicad_notation() {
    // The netlist for KiCad keeps the value; the deck has it in SPICE's notation, in which `4k7`
    // would be 4k and `1M` milli.
    let r = Resistor::new("4k7");
    assert_eq!(r.value(), "4k7");
    let args = |r: Resistor| match r.spice() {
        Some(SpicePartInfo::Elements { elements, .. }) => elements[0].args.clone(),
        other => panic!("{other:?}"),
    };
    assert_eq!(args(r), "4.7k");
    assert_eq!(args(Resistor::new("1M")), "1Meg");
    let panic = std::panic::catch_unwind(|| Resistor::new("R47")).unwrap_err();
    assert_eq!(
        panic.downcast_ref::<String>().unwrap(),
        "the value \"R47\" is not a number (like 10k, 4k7 or 1M for mega)"
    );
}

#[test]
fn test_dual_amp() {
    let amp = DualAmp::new();
    assert_eq!(
        DualAmp::PINS,
        ["out_a", "2", "3", "4", "5", "6", "out_b", "8", "ep"]
    );
    assert_eq!(DualAmp::OUT_A, "out_a");
    assert_eq!(amp.value(), "DUAL_AMP");
    assert_eq!(amp.ref_prefix(), "U");
    assert_eq!(amp.internal_connections(), vec![strings(&["4", "ep"])]);
    let info = amp.kicad().unwrap();
    assert_eq!(
        info.pins["out_a"],
        KicadPinInfo::new("1", None, PinType::Output)
    );
    assert_eq!(
        info.pins["4"],
        KicadPinInfo::new("4", Some("V-"), PinType::PowerIn)
    );
    assert_eq!(
        info.pins["ep"],
        KicadPinInfo::new("9", None, PinType::Passive)
    );
    assert_eq!(info.fields, vec![("MPN".to_string(), "DA-1".to_string())]);
    assert!(info.check_pins(&PartPins::of(&amp)).is_empty());
    assert_eq!(amp.spice(), None);
}

#[test]
fn test_regulator() {
    let reg = Regulator;
    let info = reg.kicad().unwrap();
    assert_eq!(info.footprint, Some("test:SOT-223".parse().unwrap()));
    assert!(info.flags.exclude_from_bom);
    assert_eq!(reg.internal_connections(), vec![strings(&["2", "4"])]);
    assert_eq!(reg.spice(), Some(SpicePartInfo::Excluded));
}

#[test]
fn test_inline_subcircuit() {
    let amp = Amp;
    assert_eq!(amp.kicad().unwrap().footprint, None);
    let Some(SpicePartInfo::Elements {
        elements,
        unused_pins,
    }) = amp.spice()
    else {
        panic!("{:?}", amp.spice())
    };
    assert_eq!(unused_pins, strings(&["6"]));
    assert_eq!(elements[0].nodes, strings(&["3", "2", "5", "4", "1"]));
    assert_eq!(elements[0].args, "amp GAIN=100");
    let names: Vec<_> = elements[0]
        .models
        .iter()
        .map(|m| match m {
            ModelSource::Inline { name, .. } => name.as_str(),
            other => panic!("{other:?}"),
        })
        .collect();
    assert_eq!(names, ["amp", "clamp"]);
}

#[test]
fn test_stacked_pin_notation() {
    let amp = StackedAmp;
    // A pin per pad, connected inside the part.
    assert_eq!(StackedAmp::PINS, ["1", "2", "3", "5", "4", "vee2"]);
    assert_eq!(amp.internal_connections(), vec![strings(&["4", "vee2"])]);
    let pins = amp.kicad().unwrap().pins;
    assert_eq!(
        pins["vee2"],
        KicadPinInfo::new("6", Some("V-"), PinType::PowerIn)
    );
    // The model connects the stacked pin once, through its first pad.
    let Some(SpicePartInfo::Elements {
        elements,
        unused_pins,
    }) = amp.spice()
    else {
        panic!("{:?}", amp.spice())
    };
    assert_eq!(elements[0].nodes, strings(&["3", "2", "5", "4", "1"]));
    assert_eq!(unused_pins, strings(&["vee2"]));
}

/// The golden netlists of a circuit with a stacked pin: every pad of it is a node of the net, as
/// KiCad 10 writes them (`python3 tools/compare_kicad_cli_netlist.py --library-symbols
/// --symbol-dir crates/kicad_lib/tests/fixtures/symbols tests/golden/stacked_pins.net` with
/// KiCad 10). Run with `UPDATE_GOLDEN=1` to (re)generate them.
#[test]
fn test_stacked_pin_golden() {
    let mut circuit = CircuitBuilder::new();
    let amp = circuit.instantiate_part(Named("amp", StackedAmp));
    let r1 = circuit.instantiate_part(Named("r1", Resistor::new("10k")));
    let r2 = circuit.instantiate_part(Named("r2", Resistor::new("1k")));
    circuit.connect(amp["1"], r1["1"]);
    circuit.connect(r1["2"], amp["2"]);
    circuit.connect(amp["2"], r2["1"]);
    circuit.label(r2["2"], NetLabel::global("GND"));
    circuit.label(amp["4"], NetLabel::global("GND"));
    circuit.label(amp["5"], NetLabel::global("VCC"));
    circuit.label(amp["3"], NetLabel::local("IN"));
    circuit.label(amp["1"], NetLabel::local("OUT"));
    let netlist = circuit.build(&()).to_netlist().unwrap();
    let mut out = Vec::new();
    netlist
        .to_kicad()
        .unwrap()
        .with_source("tests/kicad_part.rs")
        .write(&mut out)
        .unwrap();
    check_golden("stacked_pins.net", &String::from_utf8(out).unwrap());
    check_golden(
        "stacked_pins.cir",
        &netlist
            .to_spice()
            .unwrap()
            .with_title("stacked_pins")
            .to_string(),
    );
}

/// The generated parts work in a circuit exported to KiCad and SPICE.
#[test]
fn test_export() {
    let mut circuit = CircuitBuilder::new();
    let amp = circuit.instantiate_part(Named("amp", DualAmp::new()));
    let r1 = circuit.instantiate_part(Named("r1", Resistor::new("10k")));
    let r2 = circuit.instantiate_part(Named("r2", Resistor::new("1k")));
    circuit.connect(amp["out_a"], r1["1"]);
    circuit.connect(r1["2"], amp["2"]);
    circuit.connect(amp["2"], r2["1"]);
    circuit.label(r2["2"], NetLabel::global("GND"));
    circuit.label(amp["ep"], NetLabel::global("GND"));
    circuit.label(amp["3"], NetLabel::local("IN"));
    circuit.label(amp[DualAmp::OUT_A], NetLabel::local("OUT"));
    let netlist = circuit.build(&()).to_netlist().unwrap();
    let mut out = Vec::new();
    netlist.to_kicad().unwrap().write(&mut out).unwrap();
    let text = String::from_utf8(out).unwrap();
    assert!(
        text.contains("(libsource (lib \"test\") (part \"DUAL_AMP\")"),
        "{text}"
    );
    // V- (pad 4) and the exposed pad (9) are on GND through the internal connection.
    assert!(
        text.contains(
            "(node (ref \"U1\") (pin \"4\") (pinfunction \"V-\") (pintype \"power_in\"))"
        ),
        "{text}"
    );
    // The amplifier has no SPICE model.
    assert!(netlist.to_spice().is_err());
}

/// Hidden power input pins are connected to the global nets named after them, as in KiCad: with
/// a global label of the same name, and with what is wired to them (the net keeps the global
/// name, with a warning for its other name).
#[test]
fn test_hidden_power_pins() {
    assert_eq!(
        HiddenPowerGate.global_labels(),
        [("gnd", "GND"), ("5", "VCC"), ("6", "VCC")]
            .map(|(id, net)| (id.to_string(), net.to_string()))
    );
    let mut circuit = CircuitBuilder::new();
    let u1 = circuit.instantiate_part(Named("u1", HiddenPowerGate.with_field("MPN", "G-1")));
    let u2 = circuit.instantiate_part(Named("u2", HiddenPowerGate));
    let r1 = circuit.instantiate_part(Named("r1", Resistor::new("10k")));
    let r2 = circuit.instantiate_part(Named("r2", Resistor::new("1k")));
    circuit.label(r1["1"], NetLabel::global("VCC"));
    circuit.connect(r2["1"], u2["gnd"]);
    circuit.label(r2["1"], NetLabel::local("X"));
    for pin in ["1", "3", "4"] {
        circuit.connect(u1[pin], u2[pin]);
    }
    circuit.connect(r1["2"], u1["1"]);
    circuit.connect(r2["2"], u1["3"]);
    let netlist = circuit.build(&()).to_netlist().unwrap();
    let net_pins = |name: &str| {
        let net = netlist.nets.iter().find(|net| net.name == name).unwrap();
        let pins: Vec<String> = net
            .nodes
            .iter()
            .map(|node| {
                let ref_name = &netlist.components[node.component].ref_name;
                format!("{ref_name}-{}", node.pin_id)
            })
            .collect();
        pins
    };
    assert_eq!(net_pins("VCC"), ["R1-1", "U1-5", "U1-6", "U2-5", "U2-6"]);
    assert_eq!(net_pins("GND"), ["R2-1", "U1-gnd", "U2-gnd"]);
    assert_eq!(netlist.warnings.len(), 1, "{:?}", netlist.warnings);

    // The power nets need a driver, as in KiCad.
    let report = netlist.erc(&ErcSettings::default());
    let undriven: Vec<&str> = report
        .violations
        .iter()
        .filter_map(|v| match v.kind() {
            ErcViolationKind::PowerPinNotDriven { net, .. } => Some(net.as_str()),
            _ => None,
        })
        .collect();
    assert_eq!(undriven, ["GND", "VCC"]);
}

/// The generated code names everything by its full path, so it compiles where the user's names
/// shadow the prelude.
mod hygiene {
    #![allow(dead_code, non_snake_case, non_upper_case_globals, unused_macros)]

    struct String;
    struct Vec;
    struct Option;
    fn Some() {}
    const None: () = ();
    macro_rules! vec {
        ($($tt:tt)*) => {
            compile_error!("the user's `vec!`")
        };
    }
    macro_rules! format {
        ($($tt:tt)*) => {
            compile_error!("the user's `format!`")
        };
    }
    macro_rules! include_bytes {
        ($($tt:tt)*) => {
            compile_error!("the user's `include_bytes!`")
        };
    }
    macro_rules! option_env {
        ($($tt:tt)*) => {
            compile_error!("the user's `option_env!`")
        };
    }

    cuprite_wire::kicad_part! {
        pub struct Resistor {
            symbol: "test:R",
            footprint: "test:R_0603",
            value: param,
            symbol_dir: "crates/kicad_lib/tests/fixtures/symbols",
            footprint_dir: "crates/kicad_lib/tests/fixtures/footprints",
        }
    }

    cuprite_wire::kicad_part! {
        pub struct DualAmp {
            symbol: "test:DUAL_AMP",
            footprint: "test:SOIC-8-EP",
            pins: { "9" => "ep" },
            extra_pads: ["9"],
            internal_connections: [["4", "ep"]],
            fields: { "MPN" => "DA-1" },
            symbol_dir: "crates/kicad_lib/tests/fixtures/symbols",
            footprint_dir: "crates/kicad_lib/tests/fixtures/footprints",
        }
    }

    cuprite_wire::spice_part! {
        pub struct Clamp {
            library: "crates/kicad_lib/tests/fixtures/models/clamp.lib",
            name: "clamp",
        }
    }
}

#[test]
fn test_hygiene() {
    let resistor = hygiene::Resistor::new("10k");
    assert_eq!(resistor.value(), "10k");
    assert!(resistor.spice().is_some());
    let amp = hygiene::DualAmp::new();
    assert_eq!(amp.internal_connections(), [strings(&["4", "ep"])]);
    assert_eq!(amp.kicad().unwrap().fields, [("MPN".into(), "DA-1".into())]);
    assert_eq!(hygiene::Clamp::new().value(), "clamp");
}
